import random


def simulate_replication(seed, n_stations, warmup_periods, measured_periods):
    rng = random.Random(seed)

    # waiting[i] is the input buffer immediately before station i.
    # Station 1 draws directly from unlimited raw material.
    waiting = [0] * n_stations
    total_finished = 0

    for period in range(warmup_periods + measured_periods):
        finished_this_period = 0

        for station in range(n_stations):
            capacity = rng.randint(3, 4)

            if station == 0:
                moved = capacity
            else:
                moved = min(capacity, waiting[station])
                waiting[station] -= moved

            if station == n_stations - 1:
                finished_this_period += moved
            else:
                waiting[station + 1] += moved

        if period >= warmup_periods:
            total_finished += finished_this_period

    return total_finished


def main():
    n_stations = 5
    replications = 20
    warmup_periods = 1_000
    measured_periods = 20_000

    total_finished = 0
    for replication in range(replications):
        seed = 10_000_000 + replication * 7_919
        total_finished += simulate_replication(
            seed, n_stations, warmup_periods, measured_periods
        )

    throughput = total_finished / (replications * measured_periods)

    # Use the known distributional means so sampling noise cannot
    # incorrectly turn equal-capacity stations into a unique bottleneck.
    average_capacities = [3.5] * n_stations
    if all(capacity == average_capacities[0] for capacity in average_capacities):
        bottleneck = "none"
    else:
        bottleneck = str(
            min(range(n_stations), key=lambda i: average_capacities[i]) + 1
        )

    print(f"BOTTLENECK: {bottleneck}")
    print(f"THROUGHPUT: {throughput:.6f}")


if __name__ == "__main__":
    main()
